INSERT INTO game_task_flow_steps (layer, task_id, step_no, target_npc, kind, text, say, done) VALUES
  ('base', 1, 1, '守城卫兵阿蒙', 'collect', '在龙城守城卫兵阿蒙处接到委托：去听溪走廊、缘溪走廊或阳泉平原消灭/C10甲虫，并收集10只硬壳。', '守城卫兵阿蒙: 东西都齐了, 辛苦你了!', TRUE),
  ('base', 2, 1, '守城卫兵阿蒙', 'collect', '在龙城守城卫兵阿蒙处接到委托：去龙城西郊消灭/C10木头人，并收集10个木头零件。', '守城卫兵阿蒙: 东西都齐了, 辛苦你了!', TRUE),
  ('base', 3, 1, '守城卫兵阿蒙', 'collect', '在龙城守城卫兵阿蒙处接到委托：去一叶岭或寻仙道消灭/C10大蜗牛怪，并收集10个大蜗牛壳。', '守城卫兵阿蒙: 东西都齐了, 辛苦你了!', TRUE),
  ('base', 4, 1, '店小二阿晃', 'collect', '帮龙城店小二阿晃收集10枚蛇胆。华山上的/C10碧蛇会掉落蛇胆。', '店小二阿晃: 东西都齐了, 辛苦你了!', TRUE),
  ('base', 5, 1, '小和尚正中', 'kill', '打狐妖夺回翡翠念珠(一打得假珠/二打又是假珠/三打得真珠), 狐妖在龙城东郊、寻仙道一带出没', '小和尚正中: 这才是真的翡翠念珠! 阿弥陀佛, 多谢施主!', TRUE),
  ('base', 6, 1, '富商藤老爷', 'kill', '在华山打败10只小虎怪, 得到虎神之皮', '富商藤老爷: 打得好! 虎神之皮拿到了吗?', FALSE),
  ('base', 6, 2, '富商藤老爷', 'collect', '把虎神之皮交给富商藤老爷换取赏金', '富商藤老爷: 好一张宝皮! 这是说好的赏金, 收好。', TRUE),
  ('base', 7, 1, '矿工沙良', 'collect', '帮龙城矿工沙良寻找丢失在黄鹤遗址里的矿源之图。矿源之图是在遇见/C10木箱怪时丢失的。', '矿工沙良: 东西都齐了, 辛苦你了!', TRUE),
  ('base', 8, 1, '客栈老板卢广', 'collect', '龙城客栈老板卢广拜托你找巧匠左慈修补破裂的珐琅花瓶。', '客栈老板卢广: 东西都齐了, 辛苦你了!', TRUE),
  ('base', 11, 1, '小姑娘莺莺', 'deliver', '龙城守城卫兵阿炎请你帮他准备一束玫瑰花送给老婆，买花要找卖花的小姑娘莺莺。', '小姑娘莺莺: 知道了, 多谢你跑这一趟。', TRUE),
  ('base', 12, 1, '舞姬月影', 'collect', '龙城舞姬月影为了减肥只吃桃叶，她拜托你去采集2片桃叶。龙城北郊的桃树妖会掉落桃叶。0', '舞姬月影: 东西都齐了, 辛苦你了!', TRUE),
