  ('verified', 415, 3, '素女', 'talk', '到桃源找素女求取天花粉。', '素女: 请先替我收集5个花瓣和10个泥块。', FALSE),
  ('verified', 415, 4, '素女', 'exchange', '将5个花瓣和10个泥块交给素女，换取天花粉。', '素女: 天花粉已经配好了。', FALSE),
  ('verified', 415, 5, '仙姑门人萼绿华', 'exchange', '将天花粉交给萼绿华。', '仙姑门人萼绿华: 这正是麻姑所需的云母粉。', FALSE),
  ('verified', 415, 6, '麻姑', 'deliver', '将云母粉送给麻姑。', '麻姑: 多谢相助，我会从此潜心修道。', TRUE),
  ('verified', 418, 1, '仙姑门人萼绿华', 'talk', '替镖师孟歧向萼绿华打听丢失兵书的下落。', '仙姑门人萼绿华: 兵书被木头人偷走了。', FALSE),
  ('verified', 418, 2, '钟离门人裴谌', 'exchange', '从木头人身上夺回兵书，先拿给钟离门人裴谌查看。', '钟离门人裴谌: 我已经看过了，请把兵书还给孟歧。', FALSE),
  ('verified', 418, 3, '镖师孟歧', 'deliver', '将兵书归还镖师孟歧。', '镖师孟歧: 兵书终于找回来了。', TRUE),
  ('verified', 420, 1, '盗墓王疾风', 'talk', '替权寂道向盗墓王疾风索回青藜芭蕉扇。', '盗墓王疾风: 先把石晶变成金块再来换。', FALSE),
  ('verified', 420, 2, '权寂道', 'exchange', '从石身人面怪身上取得石晶，交给权寂道变成金块。', '权寂道: 石晶已经化成金块。', FALSE),
  ('verified', 420, 3, '盗墓王疾风', 'deliver', '把金块交给盗墓王疾风换取宝扇。', '盗墓王疾风: 宝扇已经被黄鹤遗址的轮面怪抢走了。', FALSE),
  ('verified', 420, 4, '权寂道', 'collect', '从黄鹤遗址的轮面怪身上夺回青藜芭蕉扇，交给权寂道。', '权寂道: 宝扇失而复得，我的灵力也恢复了。', TRUE),
  ('verified', 421, 1, '阿筝', 'talk', '找阿筝取回许栖岩借出的铜壶。', '阿筝: 请先替我收集10根灯芯。', FALSE),
  ('verified', 421, 2, '阿筝', 'exchange', '收集10根灯芯交给阿筝，取回铜壶。', '阿筝: 这是许栖岩借给我的铜壶。', FALSE),
  ('verified', 421, 3, '吕仙门人许栖岩', 'deliver', '将铜壶交还许栖岩。', '吕仙门人许栖岩: 铜壶已经取回来了。', TRUE),
  ('verified', 422, 1, '小和尚正中', 'deliver', '将许栖岩给的一盆白牡丹送给小和尚正中。', '小和尚正中: 我给你讲讲山石怪人的故事。', FALSE),
  ('verified', 422, 2, '吕仙门人许栖岩', 'talk', '回去把山石怪人的故事告诉许栖岩。', '吕仙门人许栖岩: 山石合在一起，原来是一个岩字。', TRUE),
  ('verified', 423, 1, '吕仙门人许栖岩', 'exchange', '从黄鹤遗址的铁钳人身上找回画轴，交给许栖岩。', '吕仙门人许栖岩: 请把画轴拿给飞鹤台的山石先生看看。', FALSE),
  ('verified', 423, 2, '山石先生', 'deliver', '将画轴交给飞鹤台的山石先生辨认。', '山石先生: 我认不出这幅画。', FALSE),
  ('verified', 423, 3, '吕仙门人许栖岩', 'talk', '回龙城向许栖岩复命。', '吕仙门人许栖岩: 看来画轴也没能唤醒他的记忆。', TRUE),
  ('verified', 424, 1, '歌姬骊姜', 'exchange', '收集10颗火灵珠、10颗地藏珠和1颗石珠，交给歌姬骊姜缝制仙袍。', '歌姬骊姜: 仙袍已经缝好，请替我送给许栖岩。', FALSE),
  ('verified', 424, 2, '吕仙门人许栖岩', 'exchange', '将仙袍送给许栖岩。', '吕仙门人许栖岩: 请把这只花簪交给山石先生。', FALSE),
  ('verified', 424, 3, '山石先生', 'deliver', '将花簪交给山石先生。', '山石先生: 前尘往事，我全都想起来了。', TRUE),
  ('verified', 426, 1, '出云隐者', 'collect', '分别从黄鱼怪、蓝鱼怪、黑蜂和玄武兽身上收集四种碎片各10片。', '出云隐者: 四种魔珠碎片已经齐了。', TRUE),
  ('verified', 427, 1, '出云隐者', 'collect', '分别从飞天猴子、大熊和苍狼皇身上取得飞天翼、灵熊掌和狼皇头。', '出云隐者: 三件材料已经齐了。', TRUE),
  ('verified', 429, 1, '出云隐者', 'collect', '分别从鹅翅面具和鹿角面具身上取得洁净的鹅翅之心和鹿角之心。', '出云隐者: 两颗洁净之心已经取得。', TRUE),
  ('verified', 431, 1, '出云隐者', 'collect', '击败青牛山的魔王飞天猪，将其魂魄收入收魂铁牌。', '出云隐者: 魔猪的魂魄已经收伏。', TRUE),
  ('verified', 433, 1, '太上老君', 'collect', '击败上天郊或后天郊的蜈蚣风筝，收集9根锁命绳。', '太上老君: 锁命绳已经齐了。', TRUE),
  ('verified', 434, 1, '太上老君', 'collect', '击败瑶池台的天判官，收集6个转运锁。', '太上老君: 转运锁已经齐了。', TRUE),
  ('verified', 435, 1, '太上老君', 'collect', '击败千年之镜的冰精灵，收集3个照劫镜。', '太上老君: 照劫镜已经齐了。', TRUE),
  ('verified', 461, 1, '莫须', 'talk', '去找莫须，帮助他唤醒与札图之间的记忆。', '莫须: 请替我找回遗失的时间锦囊。', FALSE),
  ('verified', 461, 2, '莫须', 'kill', '在无泪南郊消灭20个妖蓝水姬和20个吞噬之气，再回去找莫须。', '莫须: 我已经想起了和札图之间的友情。', FALSE),
  ('verified', 461, 3, '城门守卫札图', 'talk', '把莫须恢复记忆的消息告诉札图。', '城门守卫札图: 我们的情谊终于找回来了。', TRUE),
  ('verified', 466, 1, '阿桑', 'talk', '去找阿桑，了解他做噩梦的原因。', '阿桑: 请替我清除梦魇中的怪物。', FALSE),
  ('verified', 466, 2, '阿桑', 'kill', '消灭30个持斧小鬼和25个灰翼鬼蝠，再回去告诉阿桑。', '阿桑: 梦魇的根源已经消失了。', FALSE),
  ('verified', 466, 3, '岳林', 'talk', '回去向岳林汇报阿桑的梦魇已经清除。', '岳林: 阿桑终于可以安睡了。', TRUE),
  ('verified', 468, 1, '天镜阁长老', 'talk', '向无泪城的长老打听客栈生意不好的原因。', '天镜阁长老: 去无泪盆地寻找能够驱邪的龟灵。', FALSE),
  ('verified', 468, 2, '客栈老板富财', 'collect', '击败无泪盆地的通灵玄龟，取得驱邪龟灵交给客栈老板富财。', '客栈老板富财: 有了驱邪龟灵，客栈会恢复往日生意。', TRUE);
