-- 项目数值定案：10 级以上怪物命中取等级的 3 倍，物理防御取等级的 1 倍。
-- 魔法防御不在本次调整范围，继续保留逐怪模板值。
UPDATE game_monsters
   SET def = level,
       hit = level * 3
 WHERE level > 10;

-- 项目数值定案：攻击中心改为等级的 2 倍，再乘战斗类型与身份倍率。物理攻击
-- 在中心值上下各浮动 20%；魔攻仍为单值。精英倍率 1.3，BOSS 倍率 2。
WITH attack_scale AS (
    SELECT id,
           level * 2.0
             * CASE combat_type
                   WHEN '重型' THEN 0.75 WHEN '器物' THEN 0.75
                   WHEN '法系' THEN 0.5  WHEN '刺客' THEN 1.4
                   ELSE 1.0
               END
             * CASE kind WHEN 'BOSS' THEN 2.0 WHEN '精英' THEN 1.3 ELSE 1.0 END AS physical,
           level * 2.0
             * CASE combat_type
                   WHEN '重型' THEN 0.75 WHEN '器物' THEN 0.75
                   WHEN '法系' THEN 1.6  WHEN '刺客' THEN 0.5
                   ELSE 1.0
               END
             * CASE kind WHEN 'BOSS' THEN 2.0 WHEN '精英' THEN 1.3 ELSE 1.0 END AS magical
      FROM game_monsters
     WHERE level > 0
)
UPDATE game_monsters AS monster
   SET atk = floor(scale.physical + 0.5)::int,
       atk_min = GREATEST(1, floor(scale.physical * 0.8 + 0.5)::int),
       atk_max = GREATEST(1, floor(scale.physical * 1.2 + 0.5)::int),
       matk = floor(scale.magical + 0.5)::int
  FROM attack_scale AS scale
 WHERE monster.id = scale.id;

