-- ===== folded from 0040_work_templates.sql =====

-- 由 gamedata.ov_work 与 ov_work_bonus_entry 派生服务端工作模板。
-- 只允许按主键增量合并；禁止清表重建。

    work_id, title, lv_min, lv_max, unit_sec, unit_sec_v,
    exp, honor, coin, coin_prob,
    work_type, skill_id, pet_skill_id, pet_skill_add, practise_min, practise_max, roll_mode)
SELECT
    w.row_no,
    w.status_title,
    w.low_level,
    w.high_level,
    GREATEST(w.bonus_time_unit / 5, 1),
    w.bonus_time_unit,
    COALESCE(e.value, 0),
    COALESCE(h.value, 0),
    COALESCE(c.value, 0),
    COALESCE(c.prob, 1000),
    w.work_type,
    w.skill_id,
    w.pet_skill_id,
    w.pet_skill_add,
    w.practise_level_min,
    w.practise_level_max,
    CASE WHEN COALESCE(it.total_prob, 0) = 1000 THEN 1 ELSE 0 END
FROM gamedata.ov_work w
LEFT JOIN gamedata.ov_work_bonus_entry e ON e.row_no = w.row_no AND e.bonus_type = 3
LEFT JOIN gamedata.ov_work_bonus_entry h ON h.row_no = w.row_no AND h.bonus_type = 4
LEFT JOIN gamedata.ov_work_bonus_entry c ON c.row_no = w.row_no AND c.bonus_type = 1
LEFT JOIN (
    SELECT row_no, sum(prob) AS total_prob
      FROM gamedata.ov_work_bonus_entry
     WHERE bonus_type = 2 AND item_id > 0
     GROUP BY row_no
) it ON it.row_no = w.row_no
WHERE w.bonus_time_unit > 0
ON CONFLICT (work_id) DO UPDATE SET
    title = EXCLUDED.title,
    lv_min = EXCLUDED.lv_min,
    lv_max = EXCLUDED.lv_max,
    unit_sec = EXCLUDED.unit_sec,
    unit_sec_v = EXCLUDED.unit_sec_v,
    exp = EXCLUDED.exp,
    honor = EXCLUDED.honor,
    coin = EXCLUDED.coin,
    coin_prob = EXCLUDED.coin_prob,
    work_type = EXCLUDED.work_type,
    skill_id = EXCLUDED.skill_id,
    pet_skill_id = EXCLUDED.pet_skill_id,
    pet_skill_add = EXCLUDED.pet_skill_add,
    practise_min = EXCLUDED.practise_min,
    practise_max = EXCLUDED.practise_max,
    roll_mode = EXCLUDED.roll_mode;

SELECT b.row_no, b.idx, b.item_id, GREATEST(b.value, 1), b.prob, b.res
  FROM gamedata.ov_work_bonus_entry b
  JOIN game_work w ON w.work_id = b.row_no
 WHERE b.bonus_type = 2 AND b.item_id > 0 AND b.prob > 0
ON CONFLICT (work_id, seq) DO UPDATE SET
    item_id = EXCLUDED.item_id,
    qty = EXCLUDED.qty,
    prob = EXCLUDED.prob,
    practise_gain_max = EXCLUDED.practise_gain_max;

-- ===== 怪物技能 AI：服务端模板与结果闭合 =====

-- 模板绑定只依赖已经入库的怪物类别、战斗类型与移动能力。此后服务端启动只读
-- ai_template，不再在 Go 代码里按名字或等级临时猜策略。
UPDATE game_monsters
   SET ai_template = CASE
       WHEN kind IN ('场景物件','采集物') THEN 'passive'
       WHEN kind = 'BOSS' AND combat_type = '法系' THEN 'boss_caster'
       WHEN kind = 'BOSS' THEN 'boss_melee'
       WHEN kind = '精英' AND combat_type = '法系' THEN 'elite_caster'
       WHEN kind = '精英' THEN 'elite'
       WHEN move_speed = 0 THEN 'turret'
       WHEN combat_type = '法系' THEN 'caster'
       ELSE 'melee'
   END;

-- 火鸟蛋的客户端模型只有 stand/die 动作，没有攻击动作；它是可击杀任务物，
-- 不是移速为 0 的反击炮台。
UPDATE game_monsters SET can_attack = FALSE WHERE id = 1142;

-- 失落神殿三类阿卡哈之眼均以专用技能为唯一输出/支援手段；五颗守护石只
-- 召唤与低血恢复。公开攻略明确它们不进行普通攻击，AI仍保持启用以释放技能。
UPDATE game_monsters SET basic_attack_enabled=FALSE
 WHERE id IN (3112,3113,3114,3115,3116,3117,3118,3119,3178);

-- 原始 monsters.json 没有 Rate/RemainHPRate。这里给出服务端第一版确定规则：
-- BOSS/精英更积极，普通怪每秒最多判定一次；技能自己的 sep 非零时优先采用。
UPDATE game_monster_skills ms
   SET priority = 1000 - ms.slot * 10 + CASE WHEN ms.kind = 'self' THEN 5 ELSE 0 END,
       chance_bp = CASE m.kind WHEN 'BOSS' THEN 6500 WHEN '精英' THEN 5000 ELSE 3500 END,
       cooldown_ms = COALESCE((
           SELECT NULLIF(sd.sep,0) * 100
             FROM gamedata.ov_skilldesc sd
            WHERE sd.skill_id = ms.skill_id AND sd.skill_level = GREATEST(ms.skill_lv,1)
            ORDER BY CASE WHEN sd.prof=0 THEN 0 ELSE 1 END
            LIMIT 1
       ), CASE m.kind WHEN 'BOSS' THEN 3000 WHEN '精英' THEN 4000 ELSE 5000 END),
       initial_delay_ms = CASE m.kind WHEN 'BOSS' THEN 800 ELSE 1500 END,
       min_hp_pct = 0,
       max_hp_pct = CASE
           WHEN ms.kind='self' AND (ms.name LIKE '%治愈%' OR ms.name LIKE '%治疗%' OR
                                    ms.name LIKE '%群疗%' OR ms.name LIKE '%单奶%') THEN 60
           ELSE 100
       END,
       max_casts_per_life = 0,
       fallback_damage_pct = CASE WHEN ms.kind='enemy' THEN 100 ELSE 0 END,
       enabled = ms.kind <> 'immune'
  FROM game_monsters m
 WHERE m.id = ms.monster_id;

-- ===== BOSS 逐体选技规则 =====

-- 客户端目标位明确为自身的技能统一改成 self，不能只校正 BOSS。原始怪物表
-- 把一批普通怪/精英的狂暴术、钢铁之躯、针刺护体等写成 enemy，运行时会把
-- 增益丢给玩家。迁移到每只怪当前最大 slot 之后，既避免与已有 self 槽冲突，
-- 也保留同优先级技能的稳定顺序。伤害技能仍由闭合效果决定作用阵营；self
-- 同时负责让自身中心范围技以怪物而不是当前玩家为圆心。
WITH candidates AS (
    SELECT ms.ctid AS row_id, ms.monster_id, ms.slot
      FROM game_monster_skills ms
      JOIN LATERAL (
          SELECT sd.target_self, sd.target_mon, sd.target_team
            FROM gamedata.ov_skilldesc sd
           WHERE sd.skill_id=ms.skill_id
           ORDER BY CASE WHEN sd.skill_level=ms.skill_lv THEN 0 ELSE 1 END,
                    CASE WHEN sd.prof=0 THEN 0 ELSE 1 END,
                    ABS(sd.skill_level-GREATEST(ms.skill_lv,1))
           LIMIT 1
      ) sd ON true
     WHERE ms.kind='enemy' AND sd.target_self<>0 AND sd.target_mon=0 AND sd.target_team=0
), numbered AS (
    SELECT c.row_id,
           mx.max_slot + row_number() OVER (PARTITION BY c.monster_id ORDER BY c.slot, c.row_id) AS new_slot
      FROM candidates c
      JOIN LATERAL (
          SELECT COALESCE(max(x.slot),-1) AS max_slot
            FROM game_monster_skills x
           WHERE x.monster_id=c.monster_id
      ) mx ON true
)
UPDATE game_monster_skills ms
   SET kind='self', slot=n.new_slot
  FROM numbered n
 WHERE ms.ctid=n.row_id;

-- 下面 7 条客户端定义为自身起手/自身中心，但位移或召唤参数尚未闭合；当前
-- 可执行语义仍是一次基础技能伤害。显式保留 fallback，确保 init 重跑时不会
-- 因 kind 已校正为 self 而被上面的通用初始化清零。
UPDATE game_monster_skills
   SET fallback_damage_pct=100
 WHERE (monster_id,skill_id) IN (
    (3052,12034), (3059,12034), (3060,12034), (3061,12034), (3067,12034),
    (3001,12207), (3141,12078)
 );

