-- 缺少召唤对象，或依赖持续光环/待命触发器而当前协议无法表达的技能明确禁用。
-- 禁用规则不会进入选技，也不会阻塞这些怪物的其它技能或普攻。
UPDATE game_monster_skills
   SET enabled=FALSE, fallback_damage_pct=0,
       disabled_reason=CASE skill_id
           WHEN 12065 THEN '天将召唤对象未闭合'
           WHEN 12072 THEN '巫师召唤对象未闭合，禁止递归召唤自身'
           WHEN 12078 THEN '空间召唤对象未闭合'
           WHEN 12091 THEN '腾蛇召唤对象未闭合'
           WHEN 12092 THEN '腾蛇召唤对象未闭合'
           WHEN 12128 THEN '守卫召唤对象随场景变化，映射未闭合'
           WHEN 12129 THEN '真君召唤对象随技能等级变化，映射未闭合'
           WHEN 12199 THEN '召唤joc对象不存在于怪物表'
           WHEN 12204 THEN '召唤仙花对象不存在于怪物表'
           WHEN 12207 THEN '召唤自爆兽对象不存在于怪物表'
           WHEN 12215 THEN 'BOSS光环缺少作用属性与半径'
           WHEN 12346 THEN '发射待命依赖后续触发器，单独释放无效果'
           WHEN 35003 THEN '持续范围伤害需要独立光环时序，当前结果表无法精确表达'
           WHEN 35005 THEN '持续恐惧光环需要独立光环时序，当前结果表无法精确表达'
           WHEN 35010 THEN '法阵需要范围驻留与共享吸收池，当前结果表无法精确表达'
           ELSE '未闭合'
       END
 WHERE skill_id IN (12065,12072,12078,12091,12092,12128,12129,12199,
                    12204,12207,12215,12346,35003,35005,35010);

UPDATE game_monster_skills
   SET enabled=FALSE, fallback_damage_pct=0,
       disabled_reason=CASE skill_id
           WHEN 12080 THEN '试炼Boss被动状态缺少属性定义'
           WHEN 12536 THEN '空名自用技能缺少客户端定义与效果'
           WHEN 35001 THEN '红莲狱火为持续光环，被动时序未闭合'
       END
 WHERE skill_id IN (12080,12536,35001) AND kind<>'immune';

-- 怪物专用治疗技能的描述表为空，数值是服务端平衡配置而不是伪装成原服数据。
ON CONFLICT (skill_id,skill_lv,seq) DO UPDATE SET
    effect_kind=EXCLUDED.effect_kind, heal_max_hp_pct=EXCLUDED.heal_max_hp_pct,
    flat_value=EXCLUDED.flat_value;

-- 客户端/现有服务端协议能完整表达的场景动作。
ON CONFLICT (skill_id,skill_lv,seq) DO UPDATE SET
    effect_kind=EXCLUDED.effect_kind, duration_sec=EXCLUDED.duration_sec,
    summon_monster_id=EXCLUDED.summon_monster_id, summon_count=EXCLUDED.summon_count;

-- 怪物专用技能行大多把 hurt_type 留成0；同名职业技能与技能系别已经闭合的
-- 火/冰/光/暗法术显式覆盖伤害通道。阿卡哈物理眼则明确强制为物理必中。
UPDATE game_monster_skill_effects SET override_hurt_type=TRUE, hurt_type_override=8
 WHERE skill_id IN (12021,12022,12023,12024,12056);
UPDATE game_monster_skill_effects SET override_hurt_type=TRUE, hurt_type_override=9
 WHERE skill_id IN (12025,12026,12027);
UPDATE game_monster_skill_effects SET override_hurt_type=TRUE, hurt_type_override=12
 WHERE skill_id IN (12029,12030,12031,12032);
UPDATE game_monster_skill_effects SET override_hurt_type=TRUE, hurt_type_override=13
 WHERE skill_id IN (12041,12068,12200,12210);
UPDATE game_monster_skill_effects SET override_hurt_type=TRUE, hurt_type_override=0
 WHERE skill_id=12048;

-- 所有结构化结果加载完成后统一清掉历史 fallback。
UPDATE game_monster_skills ms
   SET fallback_damage_pct=0, disabled_reason=''
 WHERE enabled AND EXISTS (
       SELECT 1 FROM game_monster_skill_effects e WHERE e.skill_id=ms.skill_id
   );

-- 场景物件没有主动索敌入口。其余仍带 fallback 的“召唤/陷阱/结界”规则依赖
-- 专属场景脚本，不能作为怪物主动伤害执行；统一带原因禁用。
UPDATE game_monster_skills ms
   SET enabled=FALSE, fallback_damage_pct=0,
       disabled_reason='场景物件专属触发器未闭合，不进入怪物主动AI'
  FROM game_monsters m
 WHERE m.id=ms.monster_id AND m.kind='场景物件' AND ms.kind<>'immune' AND ms.enabled
   AND ms.fallback_damage_pct>0
   AND NOT EXISTS (SELECT 1 FROM game_monster_skill_effects e WHERE e.skill_id=ms.skill_id);

DO $$
DECLARE n INT;
BEGIN
    SELECT count(*) INTO n FROM (
        SELECT DISTINCT ms.monster_id,ms.kind,ms.slot
          FROM game_monster_skills ms
          JOIN map_monster_spawns sp ON sp.monster=ms.monster_id
         WHERE ms.kind<>'immune' AND ms.enabled AND ms.fallback_damage_pct>0
    ) x;
    IF n<>0 THEN RAISE EXCEPTION '仍有 % 条已落位怪物技能使用通用伤害兜底',n; END IF;

    SELECT count(*) INTO n FROM (
        SELECT DISTINCT ms.monster_id,ms.kind,ms.slot
          FROM game_monster_skills ms
          JOIN map_monster_spawns sp ON sp.monster=ms.monster_id
         WHERE ms.kind<>'immune' AND ms.enabled AND NOT EXISTS (
               SELECT 1 FROM game_monster_skill_effects e WHERE e.skill_id=ms.skill_id)
    ) x;
    IF n<>0 THEN RAISE EXCEPTION '仍有 % 条已落位启用技能没有结构化效果',n; END IF;

    SELECT count(*) INTO n FROM game_monster_skills
     WHERE kind<>'immune' AND NOT enabled AND disabled_reason='';
    IF n<>0 THEN RAISE EXCEPTION '仍有 % 条禁用怪物技能没有原因',n; END IF;
END $$;

-- 怪物硬控节奏：昏迷、冰冻、石化最多持续 3 秒，关联技能至少冷却 20 秒。
-- 仅调整怪物专用效果与选技规则；玩家技能和共享原始状态表保持原值。
-- 短于 3 秒的既有硬控、长于 20 秒的阶段技能冷却继续保留。
UPDATE game_monster_skill_effects
   SET duration_sec=3
 WHERE effect_kind IN ('status','random_status') AND status_id IN (1002,1004,1005)
   AND (duration_sec=0 OR duration_sec>3);

UPDATE game_monster_skills ms
   SET cooldown_ms=20000
 WHERE ms.kind<>'immune' AND ms.cooldown_ms<20000
   AND EXISTS (
       SELECT 1 FROM game_monster_skill_effects e
        WHERE e.skill_id=ms.skill_id AND e.skill_lv IN (0,GREATEST(ms.skill_lv,1))
          AND e.effect_kind IN ('status','random_status') AND e.status_id IN (1002,1004,1005)
   );

-- 配置闭合门禁：每只有效怪必须有模板；所有概率/血线合法；召唤目标必须存在。
DO $$
DECLARE n INT;
BEGIN
    SELECT count(*) INTO n FROM game_monsters m
      LEFT JOIN game_monster_ai_templates a ON a.id=m.ai_template
     WHERE m.level>0 AND m.hp>0 AND a.id IS NULL;
    IF n <> 0 THEN RAISE EXCEPTION '有 % 只有效怪没有 AI 模板', n; END IF;
    SELECT count(*) INTO n FROM game_monster_skills
     WHERE chance_bp NOT BETWEEN 0 AND 10000 OR min_hp_pct > max_hp_pct OR
           max_casts_per_life < 0;
    IF n <> 0 THEN RAISE EXCEPTION '有 % 条怪物技能触发规则非法', n; END IF;
    SELECT count(*) INTO n FROM game_monster_skills ms
      JOIN game_monsters m ON m.id=ms.monster_id
     WHERE m.kind='BOSS' AND m.level>0 AND m.hp>0 AND ms.enabled AND
           ms.kind<>'immune' AND ms.max_hp_pct<100;
    IF n <> 53 THEN RAISE EXCEPTION 'BOSS 血线技能应有 53 条, 实得 %', n; END IF;
    SELECT count(*) INTO n FROM game_monster_skills ms
      JOIN game_monsters m ON m.id=ms.monster_id
     WHERE m.kind='BOSS' AND m.level>0 AND m.hp>0 AND ms.enabled AND
           ms.kind<>'immune' AND ms.max_casts_per_life>0;
    IF n <> 7 THEN RAISE EXCEPTION 'BOSS 每生命限次技能应有 7 条, 实得 %', n; END IF;
    SELECT count(*) INTO n FROM game_monster_skills ms
      JOIN game_monsters m ON m.id=ms.monster_id
      LEFT JOIN LATERAL (
          SELECT sd.target_self, sd.target_mon, sd.target_team
            FROM gamedata.ov_skilldesc sd
           WHERE sd.skill_id=ms.skill_id
           ORDER BY CASE WHEN sd.skill_level=ms.skill_lv THEN 0 ELSE 1 END,
                    CASE WHEN sd.prof=0 THEN 0 ELSE 1 END,
                    ABS(sd.skill_level-GREATEST(ms.skill_lv,1))
           LIMIT 1
      ) sd ON true
     WHERE m.level>0 AND m.hp>0 AND ms.enabled AND
           ms.kind='enemy' AND COALESCE(sd.target_self,0)<>0 AND
           COALESCE(sd.target_mon,0)=0 AND COALESCE(sd.target_team,0)=0;
    IF n <> 0 THEN RAISE EXCEPTION '仍有 % 条怪物自身起手技能标成 enemy', n; END IF;
    SELECT count(*) INTO n FROM game_monster_skill_effects e
      LEFT JOIN game_monsters m ON m.id=e.summon_monster_id
     WHERE e.effect_kind='summon' AND m.id IS NULL;
    IF n <> 0 THEN RAISE EXCEPTION '有 % 条召唤技能引用不存在的怪物', n; END IF;
END $$;

DO $$
DECLARE n INT;
BEGIN
    SELECT count(*) INTO n FROM game_work;
    IF n <> 33 THEN RAISE EXCEPTION 'game_work 应有 33 行, 实得 %', n; END IF;
    SELECT count(*) INTO n FROM game_work_items;
    IF n <> 81 THEN RAISE EXCEPTION 'game_work_items 应有 81 行, 实得 %', n; END IF;
    SELECT count(*) INTO n FROM game_work WHERE title = '钓鱼中的' AND roll_mode = 1;
    IF n <> 10 THEN RAISE EXCEPTION '钓鱼应有 10 档权重单选, 实得 %', n; END IF;
    SELECT count(*) INTO n FROM game_work WHERE work_type IN (10, 11) AND skill_id = 0;
    IF n <> 0 THEN RAISE EXCEPTION '有 % 条挖矿/钓鱼工作未绑定生活技能', n; END IF;
    SELECT count(*) INTO n FROM (
        SELECT i.work_id FROM game_work_items i
          JOIN game_work w ON w.work_id = i.work_id AND w.roll_mode = 1
         GROUP BY i.work_id HAVING sum(i.prob) <> 1000) x;
    IF n <> 0 THEN RAISE EXCEPTION '有 % 个权重单选档的概率没加满 1000', n; END IF;
END $$;

-- ===== folded from 0041_quest_kill_progress.sql =====

-- 多目标任务的当前步骤击杀进度。
--
-- character_quests.progress 过去从未被推进，现作为当前步骤下标；一条步骤可同时
-- 要求最多 5 种怪物，因此击杀数必须按 monster_id 分行保存，不能再塞进单个整数。
CREATE TABLE IF NOT EXISTS character_quest_kills (
    char_id    BIGINT NOT NULL,
    task_id    INT    NOT NULL,
    monster_id INT    NOT NULL,
    progress   INT    NOT NULL CHECK (progress >= 0),
    PRIMARY KEY (char_id, task_id, monster_id),
    FOREIGN KEY (char_id, task_id)
        REFERENCES character_quests(char_id, task_id) ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS idx_character_quest_kills_char
    ON character_quest_kills(char_id);

-- ===== folded from 0042_account_gm_level.sql =====

-- GM 权限属于账号，而不是客户端可伪造的角色展示字段。
-- 0=普通玩家，1=APP，2=WIZARD，3=ARCH，4=ADMIN。
ALTER TABLE accounts
    ADD COLUMN IF NOT EXISTS gm_level SMALLINT NOT NULL DEFAULT 0;

ALTER TABLE accounts
    ADD CONSTRAINT accounts_gm_level_range CHECK (gm_level BETWEEN 0 AND 4);

COMMENT ON COLUMN accounts.gm_level IS
    'server-authoritative GM level: 0 player, 1 APP, 2 WIZARD, 3 ARCH, 4 ADMIN';

-- ===== folded from 0043_newbie_tip_seen.sql =====

-- NewbieTipBox 已读状态按角色持久化。
-- 客户端通过 0x1076 上报，进世界时服务端用 0x8054 全量种回。
CREATE TABLE IF NOT EXISTS character_seen_tips (
    char_id BIGINT      NOT NULL REFERENCES characters(id) ON DELETE CASCADE,
    tip_id  INT         NOT NULL CHECK (tip_id > 0),
    seen_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (char_id, tip_id)
);

-- ===== folded from 0044_account_banned_until.sql =====

-- 定时封禁落在账号上，确保在线目标被踢后不能立即重连。
ALTER TABLE accounts
    ADD COLUMN IF NOT EXISTS banned_until TIMESTAMPTZ;

COMMENT ON COLUMN accounts.banned_until IS
    'temporary account ban expiry; NULL means no temporary ban';
-- ===== authoritative task flows and quest-specific drops =====
-- 任务流程和专属掉落属于服务端静态业务数据，正式运行只从这些表加载。

CREATE TABLE game_task_flows (
    layer      TEXT NOT NULL CHECK (layer IN ('base', 'verified')),
    task_id    INT  NOT NULL,
    task_name  TEXT NOT NULL,
    publisher  TEXT NOT NULL,
    PRIMARY KEY (layer, task_id)
);

CREATE TABLE game_task_flow_accept_items (
    layer      TEXT NOT NULL,
    task_id    INT  NOT NULL,
    ordinal    INT  NOT NULL CHECK (ordinal > 0),
    item_id    INT  NOT NULL CHECK (item_id > 0),
    qty        INT  NOT NULL CHECK (qty > 0),
    item_name  TEXT NOT NULL,
    PRIMARY KEY (layer, task_id, ordinal),
    FOREIGN KEY (layer, task_id)
        REFERENCES game_task_flows(layer, task_id) ON DELETE CASCADE
);

CREATE TABLE game_task_flow_steps (
    layer       TEXT NOT NULL,
    task_id     INT  NOT NULL,
    step_no     INT  NOT NULL CHECK (step_no > 0),
    target_npc  TEXT NOT NULL,
    kind        TEXT NOT NULL CHECK (kind IN ('talk', 'collect', 'kill', 'deliver', 'exchange', 'turnin')),
    text        TEXT NOT NULL DEFAULT '',
    say         TEXT NOT NULL DEFAULT '',
    done        BOOLEAN NOT NULL DEFAULT FALSE,
    PRIMARY KEY (layer, task_id, step_no),
    FOREIGN KEY (layer, task_id)
        REFERENCES game_task_flows(layer, task_id) ON DELETE CASCADE
);

CREATE TABLE game_task_flow_step_items (
    layer      TEXT NOT NULL,
    task_id    INT  NOT NULL,
    step_no    INT  NOT NULL,
    phase      TEXT NOT NULL CHECK (phase IN ('collect', 'take', 'give')),
    ordinal    INT  NOT NULL CHECK (ordinal > 0),
    item_id    INT  NOT NULL CHECK (item_id > 0),
    qty        INT  NOT NULL CHECK (qty >= 0),
    item_name  TEXT NOT NULL,
    PRIMARY KEY (layer, task_id, step_no, phase, ordinal),
    FOREIGN KEY (layer, task_id, step_no)
        REFERENCES game_task_flow_steps(layer, task_id, step_no) ON DELETE CASCADE
);

CREATE TABLE game_task_flow_item_sources (
    layer           TEXT NOT NULL,
    task_id         INT  NOT NULL,
    step_no         INT  NOT NULL,
    phase           TEXT NOT NULL,
    item_ordinal    INT  NOT NULL,
    source_ordinal  INT  NOT NULL CHECK (source_ordinal > 0),
    monster_id      INT  NOT NULL CHECK (monster_id > 0),
    PRIMARY KEY (layer, task_id, step_no, phase, item_ordinal, source_ordinal),
    FOREIGN KEY (layer, task_id, step_no, phase, item_ordinal)
        REFERENCES game_task_flow_step_items(layer, task_id, step_no, phase, ordinal)
        ON DELETE CASCADE
);

CREATE TABLE game_task_flow_kills (
    layer         TEXT NOT NULL,
    task_id       INT  NOT NULL,
    step_no       INT  NOT NULL,
    ordinal       INT  NOT NULL CHECK (ordinal > 0),
    monster_id    INT  NOT NULL CHECK (monster_id > 0),
    qty           INT  NOT NULL CHECK (qty > 0),
    monster_name  TEXT NOT NULL,
    PRIMARY KEY (layer, task_id, step_no, ordinal),
    FOREIGN KEY (layer, task_id, step_no)
        REFERENCES game_task_flow_steps(layer, task_id, step_no) ON DELETE CASCADE
);

CREATE TABLE game_task_disabled (
    task_id    INT PRIMARY KEY REFERENCES game_tasks(id) ON DELETE CASCADE,
    task_name  TEXT NOT NULL
);

CREATE TABLE game_task_drop_rates (
    layer         TEXT NOT NULL DEFAULT 'verified' CHECK (layer = 'verified'),
    task_id       INT  NOT NULL,
    task_name     TEXT NOT NULL,
    step_no       INT  NOT NULL,
    monster_id    INT  NOT NULL CHECK (monster_id > 0),
    monster_name  TEXT NOT NULL,
    rate_pct      INT  NOT NULL CHECK (rate_pct BETWEEN 1 AND 100),
    tier          TEXT NOT NULL CHECK (tier IN ('guaranteed', 'high', 'medium', 'low')),
    reason        TEXT NOT NULL CHECK (reason <> ''),
    PRIMARY KEY (task_id, step_no, monster_id),
    FOREIGN KEY (layer, task_id, step_no)
        REFERENCES game_task_flow_steps(layer, task_id, step_no) ON DELETE CASCADE
);









DO $$
DECLARE n INT;
BEGIN
    SELECT count(*) INTO n FROM game_task_flows WHERE layer = 'base';
    IF n <> 372 THEN RAISE EXCEPTION 'base 任务流程应有 372 行, 实得 %', n; END IF;
    SELECT count(*) INTO n FROM game_task_flows WHERE layer = 'verified';
    IF n <> 51 THEN RAISE EXCEPTION 'verified 任务流程应有 51 行, 实得 %', n; END IF;
    SELECT count(*) INTO n FROM game_task_flow_steps WHERE layer = 'base';
    IF n <> 422 THEN RAISE EXCEPTION 'base 任务步骤应有 422 行, 实得 %', n; END IF;
    SELECT count(*) INTO n FROM game_task_flow_steps WHERE layer = 'verified';
    IF n <> 94 THEN RAISE EXCEPTION 'verified 任务步骤应有 94 行, 实得 %', n; END IF;
    SELECT count(*) INTO n FROM game_task_disabled;
    IF n <> 2 THEN RAISE EXCEPTION '禁用任务应有 2 行, 实得 %', n; END IF;
    SELECT count(*) INTO n FROM game_task_drop_rates;
    IF n <> 72 THEN RAISE EXCEPTION '任务掉率应有 72 行, 实得 %', n; END IF;
END $$;
